create table "marmeon_migrations" ("id" bigint generated by default as identity primary key, "name" varchar(255) not null unique, "module" varchar(255) not null, "batch" integer not null);
create table "marmeon_table_owners" ("table_name" varchar(255) primary key, "module" varchar(255) not null);
create table "marmeon_secret_columns" ("table_name" varchar(255) not null, "column_name" varchar(255) not null, constraint "marmeon_secret_columns_pkey" primary key ("table_name", "column_name"));
create table "marmeon_schema_markers" ("table_name" varchar(255) not null, "column_name" varchar(255) not null default '', "marker" varchar(32) not null, "value" varchar(255), constraint "marmeon_schema_markers_pkey" primary key ("table_name", "column_name", "marker"));
create table "marmeon_versions" ("name" varchar(64) primary key, "version" integer not null);
create table "accounts" ("id" bigint generated by default as identity primary key, "email" varchar(255) not null, "password" varchar(255) not null, "deleted_at" timestamptz);
create table "notes" ("id" bigint generated by default as identity primary key, "account_id" bigint not null references "accounts" ("id"), "body" text not null);
